function validate(input) {
  const [fnName, actions, values] = input;
  if (!['sum', 'factorial', 'fib'].includes(fnName)) return 'fnName must be "sum", "factorial" or "fib".';
  if (!Array.isArray(actions) || actions.length < 1 || actions.length > 100000) return 'Give 1 to 10^5 actions.';
  if (!Array.isArray(values) || values.length !== actions.length) return 'actions and values must have the same length.';
  for (let i = 0; i < actions.length; i++) {
    const args = values[i];
    if (!Array.isArray(args) || !args.every(Number.isInteger)) return 'Each entry of values is a list of integers.';
    if (actions[i] === 'getCallCount') {
      if (args.length !== 0) return 'A "getCallCount" action takes no values.';
    } else if (actions[i] !== 'call') return 'Each action is "call" or "getCallCount".';
    else if (fnName === 'sum') {
      if (args.length !== 2 || args.some(v => v < 0 || v > 100000)) return 'sum takes two numbers from 0 to 10^5.';
    } else if (args.length !== 1 || args[0] < 1 || args[0] > 10) return `${fnName} takes one number from 1 to 10.`;
  }
  return null;
}

