function adapt(input, solve, kit) {
  const [fnName, actions, values] = input;
  const fib = n => (n <= 1 ? 1 : fib(n - 1) + fib(n - 2));
  const factorial = n => (n <= 1 ? 1 : n * factorial(n - 1));
  const plain = { sum: (a, b) => a + b, fib, factorial }[fnName];
  let callCount = 0;
  const fn = (...args) => {
    callCount += 1;
    kit.trace(`${fnName}(${args.join(', ')}) runs`);
    return plain(...args);
  };
  const memoized = solve(fn);
  if (typeof memoized !== 'function') throw new Error('memoize must return a function.');
  const answer = [];
  for (let i = 0; i < actions.length; i++) {
    if (actions[i] === 'call') {
      const value = memoized(...values[i]);
      kit.trace(`memoized(${values[i].join(', ')}) returns ${value}`);
      answer.push(value);
    } else {
      kit.trace(`fn has run ${callCount} times`);
      answer.push(callCount);
    }
  }
  return answer;
}

