function generate(rand, size) {
  const names = ['sum', 'fib', 'factorial'];
  const fnName = names[Math.floor(rand() * names.length)];
  const count = size === 'small' ? 1 + Math.floor(rand() * 10) : 2000;
  // A narrow range of arguments makes repeats, and swapped pairs for sum, likely.
  const top = size === 'small' ? 3 : 40;
  const number = () => (rand() < 0.1 ? 100000 : Math.floor(rand() * (top + 1)));
  const actions = [], values = [];
  for (let i = 0; i < count; i++) {
    if (rand() < 0.3) {
      actions.push('getCallCount');
      values.push([]);
    } else {
      actions.push('call');
      values.push(fnName === 'sum' ? [number(), number()] : [1 + Math.floor(rand() * (size === 'small' ? 4 : 10))]);
    }
  }
  return [fnName, actions, values];
}
